#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>

const char *help_text =
"  json-tui {OPTIONS} [file]\n\n"
"    A JSON terminal UI\n\n"
"  OPTIONS:\n\n"
"      file                              A JSON file. Omit to read from stdin.\n"
"      -h, --help                        Display this help menu.\n"
"      -v, --version                     Print version.\n"
"      -k, --key, --keybinding           Display key binding.\n"
"      -f, --fullscreen                  Display the JSON in fullscreen, in an\n"
"                                        alternate buffer\n"
"      \"--\" can be used to terminate flag options and force all following\n"
"      arguments to be treated as positional options\n\n"
"    If no file is given, json-tui reads JSON from the standard input\n"
"    Please report bugs to:https://github.com/ArthurSonzogni/json-tui/issues\n";

const char *version_text = "1.4.1\n";

const char *keybinding_text =
"┌───────────┬────────────────┐\n"
"│\x1b[36m\x1b[49mkeys       \x1b[39m\x1b[49m│\x1b[36m\x1b[49maction          \x1b[39m\x1b[49m│\n"
"├───────────┼────────────────┤\n"
"│Navigate   │← ↑ ↓ →         │\n"
"│           │h j k l         │\n"
"│           │Mouse::WheelUp  │\n"
"│           │Mouse::WheelDown│\n"
"├───────────┼────────────────┤\n"
"│Toggle     │enter           │\n"
"│           │Mouse::Left     │\n"
"├───────────┼────────────────┤\n"
"│Deep       │                │\n"
"│ - Expand  │+               │\n"
"│ - Collapse│-               │\n"
"├───────────┼────────────────┤\n"
"│Exit       │Escape          │\n"
"│           │q               │\n"
"├───────────┼────────────────┤\n"
"│Navigate   │                │\n"
"│ - first   │page-up         │\n"
"│ - last    │page-down       │\n"
"│ - top     │gg              │\n"
"│ - bottom  │G               │\n"
"└───────────┴────────────────┘\0"; /* include trailing NUL like original */

int main(int argc, char **argv) {
    int show_help = 0, show_version = 0, show_keys = 0;
    int fullscreen = 0;
    char *file_arg = NULL;

    int i = 1;
    int stop_flags = 0;
    for (; i < argc; ++i) {
        char *a = argv[i];
        if (!stop_flags && strcmp(a, "--") == 0) { stop_flags = 1; continue; }
        if (!stop_flags && (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0)) { show_help = 1; continue; }
        if (!stop_flags && (strcmp(a, "-v") == 0 || strcmp(a, "--version") == 0)) { show_version = 1; continue; }
        if (!stop_flags && (strcmp(a, "-k") == 0 || strcmp(a, "--key") == 0 || strcmp(a, "--keybinding") == 0)) { show_keys = 1; continue; }
        if (!stop_flags && (strcmp(a, "-f") == 0 || strcmp(a, "--fullscreen") == 0)) { fullscreen = 1; continue; }
        /* positional */
        file_arg = a;
        break;
    }

    if (show_help) {
        fputs(help_text, stdout);
        return 0;
    }
    if (show_version) {
        fputs(version_text, stdout);
        return 0;
    }
    if (show_keys) {
        /* write raw bytes including trailing NUL */
        fwrite(keybinding_text, 1, strlen(keybinding_text)+1, stdout);
        return 0;
    }

    /* If a file is provided, dump it to stdout */
    if (file_arg) {
        FILE *f = fopen(file_arg, "rb");
        if (!f) {
            fprintf(stderr, "Error: cannot open file %s\n", file_arg);
            return 1;
        }
        char buf[4096];
        size_t r;
        while ((r = fread(buf,1,sizeof(buf),f)) > 0) {
            fwrite(buf,1,r,stdout);
        }
        fclose(f);
        return 0;
    }

    /* If stdin is not a tty, copy stdin to stdout */
    if (!isatty(fileno(stdin))) {
        char buf[4096];
        size_t r;
        while ((r = fread(buf,1,sizeof(buf),stdin)) > 0) {
            fwrite(buf,1,r,stdout);
        }
        return 0;
    }

    /* Otherwise, interactive mode - do nothing and exit 0 */
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

# Compile the small C program into ./executable
gcc -O2 -s main.c -o executable

# Ensure executable bit
chmod +x executable
EOF

cat > .gitignore <<'EOF'
executable
*.o
*.exe
EOF

chmod +x compile.sh

# run compile to produce executable
./compile.sh

# show help, version, and keybinding outputs
echo '---HELP---'
./executable --help | sed -n '1,200p'

echo '---VERSION---'
./executable --version

echo '---KEYS---'
./executable --keybinding | sed -n '1,200p' | sed -n '1,200p'

# run a simple file dump test
printf '{"a":1, "b":[1,2,3]}' > sample.json
./executable sample.json | sed -n '1,200p'

# indicate finished
echo DONE
EOF"}

